default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AlwaysInstallElevated', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer [AlwaysInstallElevated]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer')) {
    New-Item -Path 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer' -Name 'AlwaysInstallElevated' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
